Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int N = 1000009;
const int MOD = 1e9+7;

long long modExp(long long base, long long exp, long long mod) {
    long long result = 1, cur_base = base;
    while (exp > 0) {
        if (exp & 1) result = result * cur_base % mod;
        cur_base = cur_base * cur_base % mod;
        exp >>= 1;
    }
    return result;
}

int visited[N];

int main() {
#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int p, k;
    cin >> p >> k;
    int answer = 1;
    if (k == 0) {
        for (int i = 1; i < p; ++i)
            answer = (long long)answer * p % MOD;
        cout << answer << endl;
        return 0;
    }
    for (int i = 0; i < p; ++i) {
        if (visited[i]) continue;
        int j = i, d = 0;
        do {
            visited[j] = ++d;
            j = (long long)j * k % p;
        } while (!visited[j]);
        if (modExp(k, d, p) == 1)
            answer = (long long)answer * p % MOD;
    }
    cout << answer << endl;
#ifndef ONLINE_JUDGE
    fclose(stdin); fclose(stdout);
#endif
    return 0;
}
</original_code>
